{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The logs bucket has no bucket-level Public Access Block, leaving it vulnerable to accidental exposure through future ACL or bucket policy changes."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Log bucket permits destructive deletion",
      "resource": "aws_s3_bucket.logs",
      "severity": "HIGH",
      "explanation": "Setting force_destroy to true allows Terraform to delete the bucket and all versioned log objects, which could irreversibly remove security and audit evidence."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"
  versioning {
    enabled = true
  }
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }
  force_destroy = false
  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
",
  "fix_summary": "Added a bucket-level Public Access Block to prevent public exposure through ACLs or policies. Disabled forceful destruction so Terraform cannot automatically delete the bucket and its versioned logs."
}
